RL("stx pdf meta","kgm-0831c-r86","  en:'Staff Travel Policy',ver:'2026.09（Rev. B）',eff:'2026-09-14',pages:10,arts:29,\n  owner:'人力資源處　員工旅遊組',approver:'董事長',issued:'2026-09-05',\n  file:'15_KGM_員工票管理辦法.pdf'};","  en:'Staff Travel Policy',ver:'2026.10（Rev. C）',eff:'2026-10-06',pages:11,arts:29,\n  owner:'人力資源處　員工旅遊組',approver:'董事長',issued:'2026-10-05',\n  file:'15_KGM_員工票管理辦法.pdf'};   /* 1006A：Rev. C（與 KGM_Policies 同一份） */",1);
RL("hr pdf meta","kgm-0831c-r86","  ver:'2026.10（Rev. A）',eff:'2026-10-05',pages:13,arts:32,owner:'人力資源處',approver:'董事長',issued:'2026-10-02',\n  file:'16_KGM_員工管理辦法.pdf'};","  ver:'2026.10（Rev. B）',eff:'2026-10-06',pages:11,arts:32,owner:'人力資源處',approver:'董事長',issued:'2026-10-05',\n  file:'17_KGM_員工管理辦法.pdf'};   /* 1006A：Rev. B；彙編第 16 份改為 KGM-RSB-016 */",1);
